#!/usr/bin/env bash
# shell/aws.sh — workbench-cloud
# AWS tool configuration. Registered at tier: tools (.dotfiles-sync.yml),
# sourced unconditionally; self-guards on `command -v aws`. The module's
# getter, get-cloud-functions, is generated by workbench-core from
# register.getters[] (Core API 1.8, workbench-core D89).

# aws-update is only ever defined once the `command -v aws` guard below has
# passed, but the getter's static-grep listing can't see that runtime guard,
# so without this it would list aws-update even on hosts without aws.
# Declared *before* that guard, not after: on a host without aws, the guard
# below returns out of this file immediately, so anything placed after it (including this declaration) would never run — and
# _wb_function_available's documented fallback for "no predicate declared"
# is available, which would silently defeat this on exactly the host where
# it needs to fire.
_wb_declare_availability aws aws-update

# Ported from workbench-precursor's tools/aws.sh, unchanged.
command -v aws &>/dev/null || return 0

# ── functions ─────────────────────────────────────────────────────────────────
# Thin wrapper — the aws installer (shell/installers.sh) already handles both
# the fresh-install and update-in-place cases across every platform. Kept here
# as a short, memorable name for anyone reaching for "aws-update" out of habit.
# It goes through 'wb tools': installer files are never sourced into the
# interactive shell, so calling the installer function directly failed with
# "command not found" (workbench-core docs/decisions-log.md D94).
aws-update() {
    wb tools install aws
}
